import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { CacheFirst, StaleWhileRevalidate } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST);

// Cleanup old caches
cleanupOutdatedCaches();

// Cache Google Fonts
registerRoute(
  ({ url }) => url.origin === 'https://fonts.googleapis.com' || url.origin === 'https://fonts.gstatic.com',
  new CacheFirst({
    cacheName: 'google-fonts',
    plugins: [
      new ExpirationPlugin({ maxEntries: 20, maxAgeSeconds: 365 * 24 * 60 * 60 }),
      new CacheableResponsePlugin({ statuses: [0, 200] }),
    ],
  })
);

// Cache images
registerRoute(
  ({ request }) => request.destination === 'image',
  new StaleWhileRevalidate({
    cacheName: 'images',
    plugins: [
      new ExpirationPlugin({ maxEntries: 50, maxAgeSeconds: 30 * 24 * 60 * 60 }),
    ],
  })
);

// --- FIREBASE MESSAGING ---

// Import Firebase scripts
importScripts('https://www.gstatic.com/firebasejs/10.8.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.8.0/firebase-messaging-compat.js');

if (typeof firebase !== 'undefined') {
  // Use environment variables injected by Vite during build
  const firebaseConfig = {
    apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
    authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
    projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
    storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
    messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
    appId: import.meta.env.VITE_FIREBASE_APP_ID,
    measurementId: import.meta.env.VITE_FIREBASE_MEASUREMENT_ID
  };

  if (firebaseConfig.apiKey) {
    if (firebase.apps.length === 0) {
      firebase.initializeApp(firebaseConfig);
      const messaging = firebase.messaging();
      messaging.onBackgroundMessage((payload) => {
        // console.log('[FCM-SW] Background Message:', payload);

        // Prioritize data payload (which we now use to avoid duplicates)
        const data = payload.data || {};
        const notificationTitle = data.title || payload.notification?.title || 'Skilled Ustaad Notification';

        const notificationOptions = {
          body: data.body || payload.notification?.body || 'New update available',
          icon: '/logo-main.png',
          badge: '/logo-main.png', // Monochrome icon for status bar
          tag: data.tag || 'fcm-notification',
          data: {
            url: data.url || (data.bookingId ? `/profile/job/${data.bookingId}` : '/profile/notifications'),
            ...data
          },
          requireInteraction: true,
          vibrate: [300, 110, 300, 110, 450],
          silent: false,
          renotify: true
        };

        // Update App Badge (Notification count on icon)
        if (self.navigator && 'setAppBadge' in self.navigator) {
          const count = parseInt(data.unreadCount) || 1;
          self.navigator.setAppBadge(count).catch((error) => {
            console.error('[FCM-SW] Failed to set app badge:', error);
          });
        }

        self.registration.showNotification(notificationTitle, notificationOptions);
      });
    }
  }
}

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(clients.claim());
});

// Handle notification clicks
self.addEventListener('notificationclick', (event) => {
  // console.log('[SW] Notification Clicked:', event.notification.tag);
  event.notification.close();

  // Clear badge when clicking a notification
  if (self.navigator && 'clearAppBadge' in self.navigator) {
    self.navigator.clearAppBadge().catch(() => { });
  }

  const urlToOpen = event.notification.data?.url || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      // Check if there is already a window open
      for (let i = 0; i < windowClients.length; i++) {
        const client = windowClients[i];
        if (client.url.includes(urlToOpen) && 'focus' in client) {
          return client.focus();
        }
      }
      // If no window found, open a new one
      if (clients.openWindow) {
        return clients.openWindow(urlToOpen);
      }
    })
  );
});
